import type { Metadata } from "next";
import { SITE_NAME, SITE_URL, AUTHOR_NAME, absoluteUrl } from "@/lib/site";

export type SeoImage = { url: string; width?: number; height?: number; alt?: string };

/** Site-wide share image, generated by app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE: SeoImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${AUTHOR_NAME}: n8n Developer, Full-Stack Dev and Growth Engineer`,
};

type BuildMetadataInput = {
  /** Page title without the brand; the root template appends " | SaniForge". */
  title: string;
  description: string;
  /** Site-relative path, e.g. "/blog". Used for the canonical and og:url. */
  path: string;
  /** Social title/description when they should differ from the search snippet. */
  socialTitle?: string;
  socialDescription?: string;
  /**
   * Share image. Omit on routes that ship their own opengraph-image file
   * (home, blog posts, case studies); those files take precedence anyway.
   */
  image?: SeoImage | null;
  type?: "website" | "article" | "profile";
  /** Set when the title must not get the " | SaniForge" suffix (e.g. it is already long enough). */
  absoluteTitle?: boolean;
  keywords?: string[];
  article?: { publishedTime?: string; modifiedTime?: string; section?: string; tags?: string[] };
};

/**
 * One place that produces title, description, canonical, Open Graph and Twitter tags,
 * so no page inherits another page's social text and every page has a share image.
 */
export function buildMetadata({
  title,
  description,
  path,
  socialTitle,
  socialDescription,
  image = DEFAULT_OG_IMAGE,
  type = "website",
  absoluteTitle = false,
  keywords,
  article,
}: BuildMetadataInput): Metadata {
  const url = absoluteUrl(path);
  const ogTitle = socialTitle ?? (absoluteTitle ? title : `${title} | ${SITE_NAME}`);
  const ogDescription = socialDescription ?? description;
  const images = image ? [{ ...image, url: absoluteUrl(image.url) }] : undefined;

  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    keywords,
    alternates: { canonical: path },
    openGraph: {
      type,
      url,
      siteName: SITE_NAME,
      locale: "en_US",
      title: ogTitle,
      description: ogDescription,
      ...(images ? { images } : {}),
      ...(type === "article" && article
        ? {
            publishedTime: article.publishedTime,
            modifiedTime: article.modifiedTime,
            section: article.section,
            tags: article.tags,
            authors: [SITE_URL],
          }
        : {}),
    },
    twitter: {
      card: "summary_large_image",
      title: ogTitle,
      description: ogDescription,
      ...(images ? { images: images.map((i) => i.url) } : {}),
    },
  };
}
